/* T15 radiativity calibration curve (radiativity_table.c, generated by charts/calibrate_radiation.py):
 *  a) the compiled curve is finite, anchored at 0 dB at 200 Hz, smooth (no step above 12 dB between
 *     neighbouring control points) and interpolates the control points exactly;
 *  b) the body pressure p(t) really uses it: with R forced flat (every mode weight 1) a D3 probe's
 *     2-4 kHz level changes by more than 3 dB. */
#include "analysis.h"
#include "radiativity.h"
#include "sim.h"
#include "test_common.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>

static double band_db(const double *x, long n, double fs, double flo, double fhi)
{
    Spectrum *s = spec_make(x, n, fs, 2);
    double p = 0.0;
    for (int i = 0; i < s->n / 2; i++) {
        double f = i * s->df;
        if (f >= flo && f < fhi) p += s->mag[i] * s->mag[i];
    }
    spec_free(s);
    return 10.0 * log10(p + 1e-300);
}

static double run_band(int flat)
{
    SimOpts o = {1, 0, 0, flat};
    Sim S;
    sim_init_instrument(&S, 96000.0, &o, "D3");
    sim_set_bow(&S, 0.1, 0.1, 0.6, 0.03);
    sim_start(&S);
    Trace *tr = sim_run(&S, 2.0, NULL, NULL);
    long i0 = tr->n / 2;
    double b = band_db(tr->ch[7] + i0, tr->n - i0, tr->fs, 2000.0, 4000.0);
    trace_free(tr);
    sim_free(&S);
    return b;
}

int main(void)
{
    printf("T15 radiativity control points (Hz: dB):");
    for (int j = 0; j < RAD_NPTS; j++) printf(" %.0f:%.2f", radiativity_f[j], radiativity_db[j]);
    printf("\n");
    for (int j = 0; j < RAD_NPTS; j++) {
        CHECK(isfinite(radiativity_db[j]), "control point %d is not finite", j);
        CHECK(fabs(radiativity_eval_db(radiativity_f[j]) - radiativity_db[j]) < 1e-9, "curve misses control point %d", j);
        if (j > 0) {
            double step = fabs(radiativity_db[j] - radiativity_db[j - 1]);
            CHECK(step <= 12.0, "step of %.2f dB between %.0f and %.0f Hz (limit 12)", step, radiativity_f[j - 1], radiativity_f[j]);
            double mid = radiativity_eval_db(sqrt(radiativity_f[j - 1] * radiativity_f[j]));
            CHECK(fabs(mid - 0.5 * (radiativity_db[j] + radiativity_db[j - 1])) < 1e-9, "not linear in dB against log frequency between %.0f and %.0f Hz", radiativity_f[j - 1], radiativity_f[j]);
        }
    }
    double worst = 0.0;
    for (double f = 20.0; f < 20000.0; f *= 1.01) {
        double r = radiativity_eval_db(f);
        CHECK(isfinite(r), "R(%.1f) not finite", f);
        double g = radiativity_gain(f);
        CHECK(isfinite(g) && g > 0.0, "gain(%.1f) = %g", f, g);
        if (fabs(r) > worst) worst = fabs(r);
    }
    printf("T15 largest |R| on 20 Hz - 20 kHz: %.1f dB\n", worst);
    CHECK(fabs(radiativity_eval_db(200.0)) < 1e-9, "R(200 Hz) = %g dB, want the 0 dB anchor", radiativity_eval_db(200.0));

    double with = run_band(0), flat = run_band(1);
    printf("T15 D3 body pressure 2-4 kHz level: calibrated curve %.1f dB, R forced flat %.1f dB, difference %.1f dB\n", with, flat, with - flat);
    CHECK(fabs(with - flat) > 3.0, "the 2-4 kHz level changes by only %.2f dB when R is flat: p(t) does not use the curve", with - flat);
    TEST_DONE("test_radiation");
}
